{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    nodes_map = {n['id']: n for n in nodes}
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    retained = set(nodes_map.keys())
    removed = []
    sorted_ids = sorted(nodes_map.keys(), key=lambda id_: (-nodes_map[id_]['depth'], id_))
    for nid in sorted_ids:
        if nid not in retained:
            continue
        node = nodes_map[nid]
        if not node['removable']:
            continue
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        children_retained = [cid for cid in retained if nodes_map[cid]['parent'] == nid]
        if children_retained:
            continue
        counts = {}
        for cid in retained:
            if cid == nid:
                continue
            sym = nodes_map[cid]['symbol']
            counts[sym] = counts.get(sym, 0) + 1
        ok = all(counts.get(sym, 0) > 0 for sym in required_symbols)
        if ok:
            retained.remove(nid)
            removed.append(nid)
    retained_sorted = sorted(retained)
    return {"removed_node_ids": removed, "retained_node_ids": retained_sorted}
"}
